}

/**
 * same preconditions as generateKeysBetween.
 * n must be >= 0 (throws otherwise).
 * Returns an array of n distinct keys in sorted order.
 * If a and b are both null, returns [a0, a1, ...]
 * If one or the other is null, returns consecutive "integer"
 * keys.  Otherwise, returns relatively short keys between
 * a and b.
 * @param {string | null | undefined} a
 * @param {string | null | undefined} b
 * @param {number} n
 * @param {string=} digits
 * @param {string=} intDigits
 * @return {string[]}
 */
export function generateNKeysBetween(
  a,
  b,
  n,
  digits = undefined,
  intDigits = undefined
) {
  if (intDigits !== undefined) {
    validateIntDigits(intDigits);
  } else {
    intDigits = digits ?? BASE_52_DIGITS;
  }
  if (digits !== undefined) {
    validateDigits(digits);
  } else {
    digits = BASE_62_DIGITS;
  }

  if (n < 0) {
    // Without this guard a negative n silently returns a single key when one
    // bound is null, and recurses without bound when both are set.
    throw new Error("n must be >= 0: " + n);
  }
  if (n === 0) {
    return [];
  }
  if (n === 1) {
    return [generateKeyBetween(a, b, digits, intDigits)];
  }
  if (b == null) {
    let c = generateKeyBetween(a, b, digits, intDigits);
    const result = [c];
    for (let i = 0; i < n - 1; i++) {
      c = generateKeyBetween(c, b, digits, intDigits);
      result.push(c);
    }
    return result;
  }
  if (a == null) {
    let c = generateKeyBetween(a, b, digits, intDigits);
    const result = [c];
    for (let i = 0; i < n - 1; i++) {
      c = generateKeyBetween(a, c, digits, intDigits);
      result.push(c);
    }
    result.reverse();
    return result;
  }
  const mid = Math.floor(n / 2);
  const c = generateKeyBetween(a, b, digits, intDigits);
  return [
    ...generateNKeysBetween(a, c, mid, digits, intDigits),
    c,
    ...generateNKeysBetween(c, b, n - mid - 1, digits, intDigits),
  ];

