  }

  layers() {
    const out = [];
    for (const id of this._layers.keys()) if (this._layerLive(id)) out.push(this._matLayer(id));
    out.sort((a, b) => a.order - b.order || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
