    }
    return [{ k: 'e', id: cur.id, set: { z } }];
  }

  _op_addLayer(op) {
    const l = op.layer;
    if (!isObj(l) || typeof l.id !== 'string' || !l.id) throw new DiagramError('addLayer requires layer.id');
