  assert.deepEqual(d.elements().map(e => e.id), ['b', 'a', 'c']);
  d.apply({ type: 'reorder', id: 'a', to: 'back' });
  assert.deepEqual(d.elements().map(e => e.id), ['a', 'b', 'c']);
  d.apply({ type: 'reorder', id: 'a', to: 'forward' });
  assert.deepEqual(d.elements().map(e => e.id), ['b', 'a', 'c']);
