  a.receive(b.pendingOps()); b.receive(a.pendingOps());
  assert.deepEqual(a.toJSON(), b.toJSON());
  // undo emits op
  a.undo();
  b.receive(a.pendingOps());
  assert.deepEqual(a.toJSON(), b.toJSON());
});

