* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; font: 13px system-ui, sans-serif; color: #222; }
.hidden { display: none !important; }
.overlay { position: fixed; inset: 0; display: flex; align-items: center; justify-content: center; background: #f3f4f7; z-index: 10; }
.card { background: #fff; padding: 24px; border-radius: 8px; box-shadow: 0 2px 12px rgba(0,0,0,.1); display: flex; flex-direction: column; gap: 10px; min-width: 300px; }
.card.wide { min-width: 460px; }
.row { display: flex; gap: 8px; }
.msg { color: #c00; min-height: 1em; margin: 0; }
#docs { list-style: none; padding: 0; margin: 0; max-height: 50vh; overflow: auto; }
#docs li { display: flex; justify-content: space-between; padding: 6px; border-bottom: 1px solid #eee; cursor: pointer; }
#docs li:hover { background: #f5f8ff; }
#app { display: flex; flex-direction: column; height: 100%; }
#toolbar { display: flex; align-items: center; gap: 4px; padding: 4px 8px; border-bottom: 1px solid #ddd; background: #fafafa; flex-wrap: wrap; }
#toolbar button, #toolbar select, .filebtn { padding: 4px 8px; border: 1px solid #ccc; border-radius: 4px; background: #fff; cursor: pointer; }
#toolbar button.active { background: #dbe8ff; border-color: #1e78ff; }
.filebtn input { display: none; }
.sep { width: 1px; height: 20px; background: #ddd; margin: 0 4px; }
.grow { flex: 1; }
.status { padding: 2px 8px; border-radius: 10px; background: #eee; }
.status.online { background: #d6f5dd; }
.status.offline { background: #ffe0e0; }
main { flex: 1; display: flex; min-height: 0; }
aside { width: 220px; overflow: auto; border-right: 1px solid #ddd; padding: 8px; background: #fcfcfc; }
#right { border-right: none; border-left: 1px solid #ddd; width: 250px; }
aside h3 { margin: 6px 0; display: flex; justify-content: space-between; font-size: 13px; }
aside ul { list-style: none; padding: 0; margin: 0; }
#layers li { display: flex; gap: 4px; align-items: center; padding: 3px; border-radius: 4px; }
#layers li.active { background: #dbe8ff; }
#layers li span { flex: 1; cursor: pointer; }
#versions li { display: flex; justify-content: space-between; padding: 3px 0; }
#canvas-wrap { flex: 1; position: relative; overflow: hidden; background: #fff; }
#canvas { width: 100%; height: 100%; display: block; touch-action: none; outline: none; user-select: none; }
#minimap { position: absolute; right: 10px; bottom: 10px; width: 180px; height: 120px; background: rgba(255,255,255,.9); border: 1px solid #ccc; border-radius: 4px; }
#text-editor { position: absolute; resize: none; border: 1px dashed #1e78ff; background: rgba(255,255,255,.9); font: 14px sans-serif; text-align: center; }
#props-form { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
#props-form label { display: flex; flex-direction: column; font-size: 11px; color: #555; }
#props-form label:first-child { grid-column: span 2; }
.muted { color: #888; }
#comments li { border: 1px solid #eee; border-radius: 4px; padding: 6px; margin: 6px 0; }
#comments li.resolved { opacity: .6; }
#comments .meta { font-size: 11px; color: #777; }
#comments .reply { margin-left: 10px; border-left: 2px solid #ddd; padding-left: 6px; }
#comment-form { display: flex; flex-direction: column; gap: 4px; }
.collab { display: inline-block; padding: 2px 6px; border-radius: 10px; color: #fff; margin-right: 3px; font-size: 11px; }
.handle { fill: #fff; stroke: #1e78ff; stroke-width: 1; cursor: pointer; }
.sel-outline { fill: none; stroke: #1e78ff; stroke-dasharray: 4 2; pointer-events: none; }
.guide { stroke: #ff2d8a; stroke-width: 1; pointer-events: none; }
.marquee { fill: rgba(30,120,255,.08); stroke: #1e78ff; stroke-dasharray: 3 3; }
.commented { stroke: #ffb000 !important; }

