  if (sx) { dx += sx.d; guides.push({ x: sx.g }); } else dx = snap({ x: b.x1 + dx, y: 0 }, { grid: 10 }).x - b.x1;
  if (sy) { dy += sy.d; guides.push({ y: sy.g }); } else dy = snap({ x: 0, y: b.y1 + dy }, { grid: 10 }).y - b.y1;
  return { dx, dy, guides };
}

canvas.addEventListener('pointerdown', (ev) => {
